WITH with_windows AS (SELECT *, FIRST_VALUE(shipping_fee) IGNORE NULLS OVER (PARTITION BY status ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_shipping_fee, ROW_NUMBER() OVER (ORDER BY order_date, id) AS seq_no FROM orders) SELECT CASE WHEN shipping_fee >= 40 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, status, STDDEV_SAMP(amount) AS amount_stddev, MAX(first_known_shipping_fee) FILTER (WHERE status = 'COMPLETED') AS completed_max_first_known_shipping_fee, GROUPING_ID() AS gid FROM with_windows GROUP BY ROLLUP (CASE WHEN shipping_fee >= 40 THEN 'PREMIUM' ELSE 'STANDARD' END, status)
